const fs = await import('node:fs');
const path = globalThis.input.hwp_path;
if (!fs.existsSync(path)) {
  throw new Error('HWP file not found: ' + path);
}
const buffer = fs.readFileSync(path);
if (buffer.length === 0) {
  throw new Error('HWP file is empty');
}
globalThis.hwpBuffer = buffer;
globalThis.fontDir = globalThis.input.font_dir || null;

const mod = await import('@ohah/hwpjs');
const toPdf = mod.toPdf || (mod.default && mod.default.toPdf);
if (!toPdf) {
  throw new Error('toPdf function not found in @ohah/hwpjs');
}
const options = {};
if (globalThis.fontDir) {
  options.font_dir = globalThis.fontDir;
}
const pdfBuffer = toPdf(globalThis.hwpBuffer, options);
globalThis.pdfBuffer = pdfBuffer;

const result = {
  pdf_base64: globalThis.pdfBuffer.toString('base64'),
  size_bytes: globalThis.pdfBuffer.length
};
console.log(JSON.stringify(result));
